SELECT "users"."id", "users"."username", CAST((SUM("downvotes") - 0) AS DOUBLE PRECISION) / NULLIF(0, 0) AS "sigma", COUNT(DISTINCT CASE WHEN "downvotes" > 0 THEN "comments"."id" ELSE NULL END) AS "n_comments", COUNT(DISTINCT CASE WHEN "downvotes" > 0 THEN "story_id" ELSE NULL END) AS "n_stories", SUM("downvotes") AS "n_downvotes", CAST(SUM("downvotes") AS DOUBLE PRECISION) / NULLIF(COUNT(DISTINCT "comments"."id"), 0) AS "average_downvotes", (CAST(COUNT(DISTINCT CASE WHEN "downvotes" > 0 THEN "comments"."id" ELSE NULL END) AS DOUBLE PRECISION) / NULLIF(COUNT(DISTINCT "comments"."id"), 0)) * 100 AS "percent_downvoted" FROM "users" INNER JOIN "comments" ON "comments"."user_id" = "users"."id" WHERE "users"."banned_at" IS NULL AND "users"."deleted_at" IS NULL AND ("comments"."created_at" >= '2020-04-16 15:39:12.952729') GROUP BY "comments"."user_id" HAVING (COUNT(DISTINCT CASE WHEN "downvotes" > 0 THEN "comments"."id" ELSE NULL END) > 4 AND COUNT(DISTINCT CASE WHEN "downvotes" > 0 THEN "story_id" ELSE NULL END) > 1 AND SUM("downvotes") >= 10 AND (CAST(COUNT(DISTINCT CASE WHEN "downvotes" > 0 THEN "comments"."id" ELSE NULL END) AS DOUBLE PRECISION) / NULLIF(COUNT(DISTINCT "comments"."id"), 0)) * 100 > 10) ORDER BY "sigma" DESC NULLS LAST LIMIT 30
